class PortaDeVoz extends AudioWorkletProcessor {
  constructor() {
    super();
    this.cfg = { modo: 'voz', ptt: false, mudo: false, auto: true, limiar: -50 };
    this.ganho = 0; this.soma = 0; this.n = 0; this.bloco = Math.round(sampleRate * 0.02);
    this.piso = -70; this.aquecer = 75; this.acima = 0; this.ultimoAcima = -1e9; this.aberta = false;
    this.port.onmessage = (e) => {
      if (e.data.reiniciar) { this.piso = -70; this.aquecer = 75; }
      Object.assign(this.cfg, e.data);
    };
  }
  limiar() { return this.cfg.auto ? Math.min(-22, Math.max(this.piso + 14, -56)) : this.cfg.limiar; }
  seguirPiso(nivel) {
    if (nivel < this.piso) this.piso += (nivel - this.piso) * 0.25;
    else this.piso += Math.min(nivel - this.piso, 20) * (this.aquecer > 0 ? 0.05 : this.aberta ? 0.003 : 0.008);
    if (this.aquecer > 0) this.aquecer--;
    this.piso = Math.max(-90, Math.min(-30, this.piso));
  }
  process(entradas, saidas) {
    const medir = entradas[0][0], voz = entradas[1][0], saida = saidas[0][0];
    const len = saida.length;
    if (medir) for (let i = 0; i < medir.length; i++) this.soma += medir[i] * medir[i];
    this.n += len;
    if (this.n >= this.bloco) {
      const rms = Math.sqrt(this.soma / this.n);
      this.soma = 0; this.n = 0;
      const nivel = rms > 0 ? 20 * Math.log10(rms) : -100;
      const agora = currentTime * 1000;
      let abrir;
      if (this.cfg.modo === 'ptt') abrir = this.cfg.ptt;
      else {
        this.seguirPiso(nivel);
        this.acima = nivel > this.limiar() ? this.acima + 1 : 0;
        if (this.acima >= 2 || (this.aberta && this.acima >= 1)) this.ultimoAcima = agora;
        abrir = agora - this.ultimoAcima < 350;
      }
      if (this.cfg.mudo) abrir = false;
      this.aberta = abrir;
      this.port.postMessage({ nivel, aberta: abrir, piso: this.piso });
    }
    const k = 1 - Math.exp(-1 / (sampleRate * (this.aberta ? 0.008 : 0.035)));
    const alvo = this.aberta ? 1 : 0;
    for (let i = 0; i < len; i++) {
      this.ganho += (alvo - this.ganho) * k;
      saida[i] = voz ? voz[i] * this.ganho : 0;
    }
    return true;
  }
}
